script:
% Preserve mission-name source Δ
Create Variable Keep I Count U Quantity Cost;
Keep = 41;
I = 0;
Count = 0;
U = 1;
Quantity = 0;
Cost = 0;
Create Spacecraft Sat;
Sat.DateFormat = A1ModJulian;
Sat.Epoch = 21545;
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = @SPEED@;
Sat.VZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.SRP = Off;
FM.Drag = None;
Create Propagator P;
P.FM = FM;
P.Type = RungeKutta89;
P.InitialStepSize = 10;
P.MinStep = 10;
P.MaxStep = 10;
P.Accuracy = 1e-12;
Create XYPlot Trace Control;
Trace.XVariable = Sat.ElapsedSecs;
Trace.YVariables = {Sat.ElapsedSecs};
Control.XVariable = Sat.ElapsedSecs;
Control.YVariables = {Sat.ElapsedSecs};
Create ReportFile Values Extra;
Values.Filename = '@VALUES@';
Extra.Filename = '@EXTRA@';
Values.WriteHeaders = false;
Values.FixedWidth = false;
Values.Delimiter = ',';
Values.Precision = 17;
Extra.WriteHeaders = false;
Extra.FixedWidth = false;
Extra.Precision = 17;
Create QuaternionProduct QuatHelper;
Create Array Qx[1,4];
Qx(1,1) = 1;
Qx(1,2) = 0;
Qx(1,3) = 0;
Qx(1,4) = 1;
Create Array Qy[1,4];
Qy(1,1) = 0;
Qy(1,2) = 1;
Qy(1,3) = 0;
Qy(1,4) = 1;
Create Array Qn[1,4];
Qn(1,1) = 0;
Qn(1,2) = 0;
Qn(1,3) = 1.7320508075688772;
Qn(1,4) = -1;
Create Array Qi[1,4];
Qi(1,1) = 0;
Qi(1,2) = 0;
Qi(1,3) = 0;
Qi(1,4) = 2;
Create Array Product[1,4];
BeginMissionSequence;
Propagate 'Probe' P(Sat) {Sat.ElapsedSecs = 10};
Propagate P(Sat) {Sat.ElapsedSecs = 10};
Product = QuatHelper(Qx, Qy);
Count = Product(1,1);
U = Product(1,2);
Cost = Product(1,3);
Quantity = Product(1,4);
Report 'Witness' Values Sat.ElapsedSecs Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Keep Count U Cost Quantity;
